    # Along each row and column, fill only background gaps between same-color markers.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Complete straight gaps between repeated cells of the same non-background color.
    # Only background cells inside a bracketed gap are recolored.
    for r in range(h):
        for c in range(w):
