            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + dr, c + dc
                while rr < h and cc < w and grid[rr][cc] == bg:
                    rr += dr
                    cc += dc
                if rr < h and cc < w and grid[rr][cc] == color and (rr, cc) != (r + dr, c + dc):
                    for k in range(1, rr-r):
                        out[r+k*dr][c+k*dc] = 2
    return out", "exit_code": 0, "error": null}

